-- UniShare - checagens de consistencia dos dados (todas devem retornar 0)

USE unishare;

SELECT * FROM (
SELECT 'usuario sem biometria' AS checagem, COUNT(*) AS n FROM usuario u WHERE NOT EXISTS (SELECT 1 FROM biometria_facial b WHERE b.id_usuario = u.id_usuario)
UNION ALL SELECT 'aluno sem curso', COUNT(*) FROM aluno a WHERE NOT EXISTS (SELECT 1 FROM aluno_curso x WHERE x.id_aluno = a.id_aluno)
UNION ALL SELECT 'disponibilizacoes sobrepostas', COUNT(*) FROM disponibilizacao d1 JOIN disponibilizacao d2 ON d1.id_equipamento = d2.id_equipamento AND d1.id_disponibilizacao < d2.id_disponibilizacao AND d1.data_inicio <= d2.data_fim AND d2.data_inicio <= d1.data_fim
UNION ALL SELECT 'reservas sobrepostas', COUNT(*) FROM solicitacao s1 JOIN disponibilizacao d1 ON d1.id_disponibilizacao = s1.id_disponibilizacao JOIN solicitacao s2 ON s2.id_solicitacao > s1.id_solicitacao AND s2.status = 'APROVADA' JOIN disponibilizacao d2 ON d2.id_disponibilizacao = s2.id_disponibilizacao AND d2.id_equipamento = d1.id_equipamento WHERE s1.status = 'APROVADA' AND s1.data_inicio < s2.data_fim AND s2.data_inicio < s1.data_fim
UNION ALL SELECT 'solicitou o proprio equipamento', COUNT(*) FROM solicitacao s JOIN aluno a ON a.id_aluno = s.id_aluno JOIN disponibilizacao d ON d.id_disponibilizacao = s.id_disponibilizacao JOIN equipamento e ON e.id_equipamento = d.id_equipamento WHERE e.id_usuario_proprietario = a.id_usuario
UNION ALL SELECT 'solicitacao fora da oferta', COUNT(*) FROM solicitacao s JOIN disponibilizacao d ON d.id_disponibilizacao = s.id_disponibilizacao WHERE s.data_inicio < d.data_inicio OR s.data_fim > d.data_fim OR s.criada_em < d.criado_em
UNION ALL SELECT 'solicitou sem identidade aprovada', COUNT(*) FROM solicitacao s WHERE NOT EXISTS (SELECT 1 FROM documento_identidade di WHERE di.id_aluno = s.id_aluno AND di.status = 'APROVADO' AND di.analisado_em <= s.criada_em)
UNION ALL SELECT 'solicitou sem aceitar o termo vigente', COUNT(*) FROM solicitacao s JOIN termo_uso t ON t.publicado_em = (SELECT MAX(t2.publicado_em) FROM termo_uso t2 WHERE t2.publicado_em <= s.criada_em) JOIN aluno al ON al.id_aluno = s.id_aluno WHERE NOT EXISTS (SELECT 1 FROM aceite_termo ac WHERE ac.id_usuario = al.id_usuario AND ac.id_termo = t.id_termo AND ac.data_hora_aceite <= s.criada_em)
UNION ALL SELECT 'equipamento cadastrado sem termo aceito', COUNT(*) FROM equipamento e WHERE NOT EXISTS (SELECT 1 FROM aceite_termo ac WHERE ac.id_usuario = e.id_usuario_proprietario AND ac.data_hora_aceite <= e.criado_em)
UNION ALL SELECT 'pendente com mais de 48h', COUNT(*) FROM solicitacao WHERE status = 'PENDENTE' AND criada_em < '2026-10-26 08:00:00'
UNION ALL SELECT 'expirada fora de 48h', COUNT(*) FROM solicitacao s JOIN registro_operacao r ON r.tabela_afetada = 'solicitacao' AND r.id_afetado = s.id_solicitacao AND r.tipo_operacao = 'EXPIRACAO' WHERE TIMESTAMPDIFF(HOUR, s.criada_em, r.data_hora) <> 48
UNION ALL SELECT 'aprovada sem reserva', COUNT(*) FROM solicitacao s WHERE s.status = 'APROVADA' AND NOT EXISTS (SELECT 1 FROM reserva r WHERE r.id_solicitacao = s.id_solicitacao)
UNION ALL SELECT 'reserva de solicitacao nao aprovada', COUNT(*) FROM reserva r JOIN solicitacao s ON s.id_solicitacao = r.id_solicitacao WHERE s.status <> 'APROVADA'
UNION ALL SELECT 'pagamento inconsistente', COUNT(*) FROM pagamento_simulado p JOIN solicitacao s ON s.id_solicitacao = p.id_solicitacao JOIN disponibilizacao d ON d.id_disponibilizacao = s.id_disponibilizacao WHERE d.modalidade <> 'ALUGUEL' OR p.valor_total <> d.valor_diaria * DATEDIFF(s.data_fim, s.data_inicio) OR (p.status = 'SIMULADO') <> (s.status IN ('APROVADA', 'PENDENTE')) OR p.data_hora < s.criada_em
UNION ALL SELECT 'aluguel sem pagamento', COUNT(*) FROM solicitacao s JOIN disponibilizacao d ON d.id_disponibilizacao = s.id_disponibilizacao WHERE d.modalidade = 'ALUGUEL' AND NOT EXISTS (SELECT 1 FROM pagamento_simulado p WHERE p.id_solicitacao = s.id_solicitacao)
UNION ALL SELECT 'biometria da retirada nao e do titular', COUNT(*) FROM retirada rt JOIN reserva r ON r.id_reserva = rt.id_reserva JOIN solicitacao s ON s.id_solicitacao = r.id_solicitacao JOIN aluno a ON a.id_aluno = s.id_aluno JOIN biometria_facial b ON b.id_biometria = rt.id_biometria WHERE b.id_usuario <> a.id_usuario OR b.criado_em > rt.data_hora
UNION ALL SELECT 'retirada antes do inicio ou da aprovacao', COUNT(*) FROM retirada rt JOIN reserva r ON r.id_reserva = rt.id_reserva JOIN solicitacao s ON s.id_solicitacao = r.id_solicitacao WHERE DATE(rt.data_hora) < s.data_inicio OR rt.data_hora < s.respondida_em
UNION ALL SELECT 'devolucao antes da retirada', COUNT(*) FROM devolucao dv JOIN retirada rt ON rt.id_retirada = dv.id_retirada WHERE dv.data_hora <= rt.data_hora
UNION ALL SELECT 'status da reserva incoerente', COUNT(*) FROM reserva r JOIN solicitacao s ON s.id_solicitacao = r.id_solicitacao LEFT JOIN retirada rt ON rt.id_reserva = r.id_reserva LEFT JOIN devolucao dv ON dv.id_retirada = rt.id_retirada WHERE NOT (
     (r.status = 'CONFIRMADA' AND rt.id_retirada IS NULL)
  OR (r.status = 'EM_USO' AND rt.id_retirada IS NOT NULL AND dv.id_devolucao IS NULL AND s.data_fim >= '2026-10-28')
  OR (r.status = 'ATRASADA' AND rt.id_retirada IS NOT NULL AND dv.id_devolucao IS NULL AND s.data_fim < '2026-10-28')
  OR (r.status = 'CONCLUIDA' AND dv.id_devolucao IS NOT NULL))
UNION ALL SELECT 'solicitacao durante manutencao', COUNT(*) FROM solicitacao s JOIN disponibilizacao d ON d.id_disponibilizacao = s.id_disponibilizacao JOIN dano dn ON dn.id_equipamento = d.id_equipamento WHERE s.criada_em >= dn.data_hora AND s.criada_em < COALESCE(dn.resolvido_em, '2099-01-01')
UNION ALL SELECT 'solicitou com atraso pendente', COUNT(*) FROM solicitacao s2 JOIN solicitacao s1 ON s1.id_aluno = s2.id_aluno JOIN reserva r ON r.id_solicitacao = s1.id_solicitacao JOIN retirada rt ON rt.id_reserva = r.id_reserva LEFT JOIN devolucao dv ON dv.id_retirada = rt.id_retirada WHERE s2.criada_em >= TIMESTAMP(s1.data_fim + INTERVAL 1 DAY) AND s2.criada_em < COALESCE(dv.data_hora, '2099-01-01')
UNION ALL SELECT 'solicitou com dano pendente', COUNT(*) FROM solicitacao s2 JOIN solicitacao s1 ON s1.id_aluno = s2.id_aluno JOIN reserva r ON r.id_solicitacao = s1.id_solicitacao JOIN dano dn ON dn.id_reserva = r.id_reserva WHERE s2.criada_em >= dn.data_hora AND s2.criada_em < COALESCE(dn.resolvido_em, '2099-01-01')
UNION ALL SELECT 'situacao do equipamento incoerente', COUNT(*) FROM equipamento e WHERE e.situacao <> CASE
    WHEN EXISTS (SELECT 1 FROM dano dn WHERE dn.id_equipamento = e.id_equipamento AND dn.status_andamento <> 'RESOLVIDO') THEN 'EM_MANUTENCAO'
    WHEN EXISTS (SELECT 1 FROM reserva r JOIN solicitacao s ON s.id_solicitacao = r.id_solicitacao JOIN disponibilizacao d ON d.id_disponibilizacao = s.id_disponibilizacao WHERE d.id_equipamento = e.id_equipamento AND r.status IN ('EM_USO', 'ATRASADA')) THEN 'EM_USO'
    WHEN EXISTS (SELECT 1 FROM reserva r JOIN solicitacao s ON s.id_solicitacao = r.id_solicitacao JOIN disponibilizacao d ON d.id_disponibilizacao = s.id_disponibilizacao WHERE d.id_equipamento = e.id_equipamento AND r.status = 'CONFIRMADA') THEN 'RESERVADO'
    WHEN EXISTS (SELECT 1 FROM disponibilizacao d WHERE d.id_equipamento = e.id_equipamento AND '2026-10-28' BETWEEN d.data_inicio AND d.data_fim) THEN 'DISPONIVEL'
    ELSE 'INDISPONIVEL' END
UNION ALL SELECT 'avaliacao invalida', COUNT(*) FROM avaliacao av JOIN reserva r ON r.id_reserva = av.id_reserva JOIN solicitacao s ON s.id_solicitacao = r.id_solicitacao JOIN disponibilizacao d ON d.id_disponibilizacao = s.id_disponibilizacao JOIN equipamento e ON e.id_equipamento = d.id_equipamento JOIN aluno aa ON aa.id_aluno = av.id_aluno_avaliador LEFT JOIN retirada rt ON rt.id_reserva = r.id_reserva LEFT JOIN devolucao dv ON dv.id_retirada = rt.id_retirada WHERE dv.id_devolucao IS NULL OR av.data_hora <= dv.data_hora OR (av.id_aluno_avaliador <> s.id_aluno AND aa.id_usuario <> e.id_usuario_proprietario)
UNION ALL SELECT 'acao sem log correspondente',
    (SELECT COUNT(*) FROM solicitacao s JOIN aluno a ON a.id_aluno = s.id_aluno WHERE NOT EXISTS (SELECT 1 FROM registro_operacao r WHERE r.tipo_operacao = 'SOLICITACAO' AND r.id_afetado = s.id_solicitacao AND r.data_hora = s.criada_em AND r.id_usuario = a.id_usuario))
  + (SELECT COUNT(*) FROM solicitacao s JOIN disponibilizacao d ON d.id_disponibilizacao = s.id_disponibilizacao JOIN equipamento e ON e.id_equipamento = d.id_equipamento WHERE s.status = 'APROVADA' AND NOT EXISTS (SELECT 1 FROM registro_operacao r WHERE r.tipo_operacao = 'APROVACAO' AND r.id_afetado = s.id_solicitacao AND r.data_hora = s.respondida_em AND r.id_usuario = e.id_usuario_proprietario))
  + (SELECT COUNT(*) FROM solicitacao s WHERE s.status = 'RECUSADA' AND NOT EXISTS (SELECT 1 FROM registro_operacao r WHERE r.tipo_operacao IN ('RECUSA', 'RECUSA_AUTOMATICA') AND r.id_afetado = s.id_solicitacao AND r.data_hora = s.respondida_em))
  + (SELECT COUNT(*) FROM retirada x WHERE NOT EXISTS (SELECT 1 FROM registro_operacao r WHERE r.tipo_operacao = 'RETIRADA' AND r.id_afetado = x.id_retirada AND r.data_hora = x.data_hora))
  + (SELECT COUNT(*) FROM devolucao x WHERE NOT EXISTS (SELECT 1 FROM registro_operacao r WHERE r.tipo_operacao = 'DEVOLUCAO' AND r.id_afetado = x.id_devolucao AND r.data_hora = x.data_hora))
  + (SELECT COUNT(*) FROM dano x WHERE NOT EXISTS (SELECT 1 FROM registro_operacao r WHERE r.tipo_operacao = 'REGISTRO_DANO' AND r.id_afetado = x.id_dano AND r.data_hora = x.data_hora AND r.id_usuario = x.id_usuario_relator))
  + (SELECT COUNT(*) FROM avaliacao x JOIN aluno a ON a.id_aluno = x.id_aluno_avaliador WHERE NOT EXISTS (SELECT 1 FROM registro_operacao r WHERE r.tipo_operacao = 'AVALIACAO' AND r.id_afetado = x.id_avaliacao AND r.data_hora = x.data_hora AND r.id_usuario = a.id_usuario))
  + (SELECT COUNT(*) FROM documento_identidade x WHERE NOT EXISTS (SELECT 1 FROM registro_operacao r WHERE r.tipo_operacao = 'ENVIO_DOCUMENTO' AND r.id_afetado = x.id_documento AND r.data_hora = x.enviado_em))
  + (SELECT COUNT(*) FROM equipamento x WHERE NOT EXISTS (SELECT 1 FROM registro_operacao r WHERE r.tipo_operacao = 'CADASTRO_EQUIPAMENTO' AND r.id_afetado = x.id_equipamento AND r.data_hora = x.criado_em AND r.id_usuario = x.id_usuario_proprietario))
  + (SELECT COUNT(*) FROM disponibilizacao x WHERE NOT EXISTS (SELECT 1 FROM registro_operacao r WHERE r.tipo_operacao = 'DISPONIBILIZACAO' AND r.id_afetado = x.id_disponibilizacao AND r.data_hora = x.criado_em))
  + (SELECT COUNT(*) FROM biometria_facial x WHERE NOT EXISTS (SELECT 1 FROM registro_operacao r WHERE r.tipo_operacao = 'CADASTRO_BIOMETRIA' AND r.id_afetado = x.id_biometria AND r.data_hora = x.criado_em AND r.id_usuario = x.id_usuario))
UNION ALL SELECT 'log apontando para registro inexistente', COUNT(*) FROM registro_operacao r WHERE
     (r.tabela_afetada = 'solicitacao' AND NOT EXISTS (SELECT 1 FROM solicitacao x WHERE x.id_solicitacao = r.id_afetado))
  OR (r.tabela_afetada = 'usuario' AND NOT EXISTS (SELECT 1 FROM usuario x WHERE x.id_usuario = r.id_afetado))
  OR (r.tabela_afetada = 'retirada' AND NOT EXISTS (SELECT 1 FROM retirada x WHERE x.id_retirada = r.id_afetado))
  OR (r.tabela_afetada = 'devolucao' AND NOT EXISTS (SELECT 1 FROM devolucao x WHERE x.id_devolucao = r.id_afetado))
  OR (r.tabela_afetada = 'dano' AND NOT EXISTS (SELECT 1 FROM dano x WHERE x.id_dano = r.id_afetado))
  OR (r.tabela_afetada = 'aceite_termo' AND NOT EXISTS (SELECT 1 FROM aceite_termo x WHERE x.id_termo = r.id_afetado AND x.data_hora_aceite = r.data_hora))
UNION ALL SELECT 'acao de usuario sem login no dia', COUNT(*) FROM registro_operacao r WHERE r.id_usuario IS NOT NULL AND r.tipo_operacao NOT IN ('LOGIN', 'CADASTRO_CONTA') AND NOT EXISTS (SELECT 1 FROM registro_operacao l WHERE l.tipo_operacao = 'LOGIN' AND l.id_usuario = r.id_usuario AND DATE(l.data_hora) = DATE(r.data_hora) AND l.data_hora <= r.data_hora)
UNION ALL SELECT 'acao apos termo novo sem aceite', COUNT(*) FROM registro_operacao r WHERE r.id_usuario IS NOT NULL AND r.data_hora >= '2026-10-01' AND r.tipo_operacao NOT IN ('LOGIN', 'LOGIN_FALHA', 'ACEITE_TERMO', 'CADASTRO_CONTA', 'CADASTRO_BIOMETRIA', 'ENVIO_DOCUMENTO') AND EXISTS (SELECT 1 FROM aceite_termo a0 WHERE a0.id_usuario = r.id_usuario) AND NOT EXISTS (SELECT 1 FROM aceite_termo ac JOIN termo_uso t ON t.id_termo = ac.id_termo WHERE ac.id_usuario = r.id_usuario AND t.versao = '1.1' AND ac.data_hora_aceite <= r.data_hora)
UNION ALL SELECT 'acao apos bloqueio da conta', COUNT(*) FROM registro_operacao r JOIN usuario u ON u.id_usuario = r.id_usuario WHERE u.status_conta = 'BLOQUEADA' AND r.data_hora > '2026-10-26 23:00:00'
UNION ALL SELECT 'aluno trancado agindo apos 30/09', COUNT(*) FROM registro_operacao r JOIN aluno a ON a.id_usuario = r.id_usuario WHERE a.situacao_vinculo = 'TRANCADO' AND r.data_hora >= '2026-09-30'
) t;
